WITH mun AS (SELECT * FROM UNNEST(['2930766','2918100','2900355','2929701','2926509','2909208']) AS id_municipio),car AS (SELECT REPLACE(id_imovel,'-','') id_car_norm,id_imovel,id_municipio,area FROM `basedosdados.br_sfb_sicar.area_imovel` JOIN mun USING(id_municipio) WHERE data_extracao>=DATE '2026-06-02' AND data_extracao<=DATE '2026-08-04' QUALIFY ROW_NUMBER() OVER(PARTITION BY REPLACE(id_imovel,'-','') ORDER BY data_extracao DESC)=1),p AS (SELECT DISTINCT ano_emissao,id_referencia_bacen,numero_ordem,REPLACE(id_car,'-','') id_car_norm FROM `basedosdados.br_bcb_sicor.recurso_publico_propriedade` WHERE ano_emissao BETWEEN 2013 AND 2026 AND id_car IS NOT NULL AND TRIM(id_car)!=''),link AS (SELECT p.ano_emissao,p.id_referencia_bacen,p.numero_ordem,p.id_car_norm,c.id_municipio,c.area FROM p JOIN car c USING(id_car_norm)),micro_ops AS (SELECT DISTINCT l.ano_emissao,l.id_referencia_bacen,l.numero_ordem,l.id_municipio FROM link l WHERE l.area<0.1),mixed AS (SELECT m.id_municipio,m.ano_emissao,m.id_referencia_bacen,m.numero_ordem,COUNT(DISTINCT IF(l.area<0.1,l.id_car_norm,NULL)) micro_imoveis,COUNT(DISTINCT IF(l.area>=1,l.id_car_norm,NULL)) imoveis_maiores FROM micro_ops m JOIN link l USING(ano_emissao,id_referencia_bacen,numero_ordem,id_municipio) GROUP BY 1,2,3,4) SELECT id_municipio,COUNT(*) operacoes_mistas,COUNTIF(imoveis_maiores>0) operacoes_com_micro_e_maior,COUNT(DISTINCT IF(imoveis_maiores>0,id_referencia_bacen,NULL)) referencias_com_micro_e_maior FROM mixed WHERE imoveis_maiores>0 GROUP BY id_municipio ORDER BY id_municipio